  currency = self.env['res.currency'].search([('id', '=', rec.x_studio_currency_id.id),('date', '<=', datetime.datetime.now().date()),('active', '=', True)],limit=1)
  if currency:
    rec['x_studio_lc_amount_lcy'] = round((rec.x_studio_lc_amount / currency.rate),2)
  else:
    raise Warning('There is no Valid Exchange Rate for the Selected Currency.')

for record  in self:
  if record.x_studio_tolerance_type == "Plus":
    record[("x_studio_revised_lc_amount")] = record.x_studio_lc_amount + (record.x_studio_lc_amount * record.x_studio_tolerance / 100)
  if record.x_studio_tolerance_type == "Minus":
    record[("x_studio_revised_lc_amount")] = record.x_studio_lc_amount - (record.x_studio_lc_amount * record.x_studio_tolerance / 100)

