for record  in self:
  if record.x_studio_exchange_rate != 0.00:
    if record.x_studio_cost_allocation_method == 'by_current_cost_price':
      record[("x_studio_allocate_amount")] = (record.product_qty * record.price_unit) * record.x_studio_exchange_rate
    elif record.x_studio_cost_allocation_method == 'by_weight':
      record[("x_studio_allocate_amount")] = (record.product_qty * record.x_studio_weight)
    elif record.x_studio_cost_allocation_method == 'by_volume':
      record[("x_studio_allocate_amount")] = (record.product_qty * record.x_studio_volume)
    else:
      record[("x_studio_allocate_amount")] = (record.product_qty * record.price_unit) * record.x_studio_exchange_rate
  else:
    record[("x_studio_allocate_amount")] = 0.00

