for rec in self:
  val = 0
  no_of_hours = 0
  difference_in_hours = 0
  target_date = datetime.date.today()
  target_date = target_date.strftime('%Y-%m-%d')
  date_start = f'{target_date} 00:00:00'
  date_end = f'{target_date} 23:59:59'

  time_now = datetime.datetime.now()
  for emp in rec.x_studio_employees:
    if emp:
      attendance = self.env['hr.attendance'].search([('employee_id', '=', emp.id),('check_in', '>=', date_start),('check_in', '<=', date_end),('x_studio_ot_entry', '=', True)],limit=1)
      if attendance:
        no_of_hours = (time_now - attendance.check_in)
        difference_in_hours = no_of_hours.total_seconds() / 3600
        if difference_in_hours > 1.00:
          val += emp.x_studio_ot_rate * emp.x_studio_employee_rate
      else:
          val += emp.x_studio_employee_rate

  rec['x_studio_ot_cost_per_hour'] = val

